//! Exact exchange-message fixtures generated by the pinned TypeScript reference.

use std::error::Error;

use serde::Deserialize;
use signify_keri::event::EventError;
use signify_keri::event::exchange::{ExchangeBuilder, ExchangeEmbed, ExchangeMessage};
use signify_keri::event::timestamp::Timestamp;
use signify_keri::prefix::IdentifierPrefix;
use signify_keri::said::Said;
use signify_keri::serialization::{Sad, SadValue, SerializedEvent};

const REFERENCE_SHA: &str = "ae92eceb8e776ad57669707bff7f84db9390b711";

#[derive(Debug, Deserialize)]
struct Fixture {
    schema_version: u8,
    upstream: String,
    reference_sha: String,
    generated_on: String,
    sources: Vec<String>,
    embedded_events: EmbeddedEvents,
    signature: String,
    cases: Vec<ExchangeCase>,
    upstream_unit_test: UpstreamUnitTest,
    count_boundary: CountBoundary,
    reference_quirks: ReferenceQuirks,
}

#[derive(Debug, Deserialize)]
struct EmbeddedEvents {
    icp: String,
    vcp: String,
}

#[derive(Debug, Deserialize)]
struct ExchangeCase {
    name: String,
    route: String,
    sender: String,
    recipient: String,
    timestamp: String,
    prior: Option<String>,
    payload_json: String,
    modifiers_json: String,
    embeds: Vec<EmbedCase>,
    said: String,
    embeds_said: Option<String>,
    version_string: String,
    raw: String,
    raw_hex: String,
    raw_byte_size: usize,
    attachments: String,
    attachments_length: usize,
    reparse: Reparse,
}

#[derive(Debug, Deserialize)]
struct EmbedCase {
    label: String,
    event_raw: String,
    attachment: Option<String>,
}

#[derive(Debug, Deserialize)]
struct Reparse {
    raw_identical: bool,
    size: usize,
    said: String,
}

#[derive(Debug, Deserialize)]
struct UpstreamUnitTest {
    source: String,
    sender: String,
    recipient: String,
    timestamp: String,
    no_embeds: UnitTestMessage,
    with_embeds: UnitTestMessage,
    note: String,
    rust_decision: String,
}

#[derive(Debug, Deserialize)]
struct UnitTestMessage {
    said: String,
    #[expect(
        dead_code,
        reason = "recorded for provenance; the block SAID is asserted through `cases`"
    )]
    embeds_said: Option<String>,
    raw: String,
    attachments: String,
}

#[derive(Debug, Deserialize)]
struct CountBoundary {
    path_quadlets: usize,
    max_accepted: MaxAccepted,
    rejected: Rejected,
}

#[derive(Debug, Deserialize)]
struct MaxAccepted {
    quadlets: usize,
    attachment_length: usize,
    attachments_prefix: String,
    attachments_length: usize,
    attachments_sha256: String,
}

#[derive(Debug, Deserialize)]
struct Rejected {
    quadlets: usize,
    threw: bool,
    error_message: String,
}

#[derive(Debug, Deserialize)]
struct ReferenceQuirks {
    the_timestamp_defaults_to_the_system_clock: ClockQuirk,
    sender_and_recipient_are_unvalidated_text: RawQuirk,
    the_payload_overrides_the_recipient: RawQuirk,
    an_embed_labelled_d_destroys_itself: RawQuirk,
    an_embed_labelled_v_throws: ThrowQuirk,
    a_separator_in_a_label_changes_the_path: AttachmentQuirk,
    an_empty_label_is_accepted: AttachmentQuirk,
    numeric_labels_are_hoisted: RawQuirk,
    a_misaligned_attachment_truncates_its_count: AttachmentQuirk,
    a_non_cesr_attachment_is_embedded_verbatim: AttachmentQuirk,
    the_payload_and_modifiers_need_not_be_maps: LooseArgumentsQuirk,
}

#[derive(Debug, Deserialize)]
struct ClockQuirk {
    shape: String,
    length: usize,
    note: String,
    rust_decision: String,
}

#[derive(Debug, Deserialize)]
struct RawQuirk {
    raw: String,
    note: String,
    #[serde(default)]
    rust_error_category: Option<String>,
    #[serde(default)]
    rust_decision: Option<String>,
}

#[derive(Debug, Deserialize)]
struct ThrowQuirk {
    threw: bool,
    error_message: String,
    note: String,
    rust_error_category: String,
}

#[derive(Debug, Deserialize)]
struct AttachmentQuirk {
    attachments: String,
    note: String,
    rust_error_category: String,
}

#[derive(Debug, Deserialize)]
struct LooseArgumentsQuirk {
    string_payload: String,
    array_payload: String,
    null_modifiers: String,
    string_modifiers: String,
    note: String,
    rust_decision: String,
}

fn fixture() -> Result<Fixture, Box<dyn Error>> {
    Ok(serde_json::from_str(include_str!(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../fixtures/keri-exchange/v1.json"
    )))?)
}

fn decode_hex(input: &str) -> Result<Vec<u8>, Box<dyn Error>> {
    if !input.len().is_multiple_of(2) {
        return Err("odd-length hexadecimal fixture field".into());
    }
    (0..input.len())
        .step_by(2)
        .map(|index| {
            input
                .get(index..index + 2)
                .ok_or_else(|| Box::<dyn Error>::from("hexadecimal fixture slice out of range"))
                .and_then(|pair| u8::from_str_radix(pair, 16).map_err(Into::into))
        })
        .collect()
}

/// Rebuilds one recorded case with the Rust builder.
fn rebuild(case: &ExchangeCase) -> Result<ExchangeMessage, Box<dyn Error>> {
    let mut builder = ExchangeBuilder::new(
        case.route.clone(),
        IdentifierPrefix::from_qb64(&case.sender)?,
        IdentifierPrefix::from_qb64(&case.recipient)?,
        Timestamp::parse(&case.timestamp)?,
    )
    .payload(Sad::from_json_bytes(case.payload_json.as_bytes())?)
    .modifiers(Sad::from_json_bytes(case.modifiers_json.as_bytes())?);
    if let Some(prior) = &case.prior {
        builder = builder.prior(Said::from_qb64(prior)?);
    }

    let mut embeds = Vec::new();
    for embed in &case.embeds {
        let event = SerializedEvent::parse(embed.event_raw.as_bytes())?;
        let built = ExchangeEmbed::new(embed.label.clone(), &event)?;
        embeds.push(match &embed.attachment {
            Some(attachment) => built.with_attachment(attachment.as_bytes())?,
            None => built,
        });
    }
    Ok(builder.embeds(embeds).build()?)
}

#[test]
fn fixture_metadata_matches_the_pinned_reference() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.schema_version, 1);
    assert_eq!(fixture.upstream, "https://github.com/WebOfTrust/signify-ts.git");
    assert_eq!(fixture.reference_sha, REFERENCE_SHA);
    assert_ne!(fixture.generated_on, "");
    assert_eq!(
        fixture.sources,
        ["src/keri/app/exchanging.ts", "test/app/exchanging.test.ts"]
    );
    // Both embedded messages parse as KERI events, and the signature is quadlet-aligned CESR text.
    SerializedEvent::parse(fixture.embedded_events.icp.as_bytes())?;
    SerializedEvent::parse(fixture.embedded_events.vcp.as_bytes())?;
    assert!(fixture.signature.len().is_multiple_of(4));
    Ok(())
}

#[test]
fn every_reference_exchange_is_reproduced_byte_for_byte() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.cases.len(), 11);

    for case in &fixture.cases {
        let expected = decode_hex(&case.raw_hex)?;
        assert_eq!(expected, case.raw.as_bytes(), "case {} hex/text disagree", case.name);
        assert_eq!(expected.len(), case.raw_byte_size, "case {}", case.name);

        let message = rebuild(case)?;
        assert_eq!(
            core::str::from_utf8(message.raw())?,
            case.raw,
            "case {} bytes differ",
            case.name
        );
        assert_eq!(message.said().qb64()?, case.said, "case {}", case.name);
        assert_eq!(
            message.sad().get_text("v"),
            Some(case.version_string.as_str()),
            "case {}",
            case.name
        );
        assert_eq!(message.raw().len(), case.raw_byte_size, "case {}", case.name);

        // The transposed attachment stream is the second half of the reference's return value.
        assert_eq!(
            core::str::from_utf8(message.attachments())?,
            case.attachments,
            "case {} attachments differ",
            case.name
        );
        assert_eq!(
            message.attachments().len(),
            case.attachments_length,
            "case {}",
            case.name
        );

        // The embeds block carries its own identifier exactly when it has embeds.
        let embeds = message
            .sad()
            .get("e")
            .and_then(SadValue::as_map)
            .ok_or("no embeds block")?;
        assert_eq!(
            embeds.get_text("d").map(str::to_owned),
            case.embeds_said,
            "case {} embeds identifier",
            case.name
        );

        // Reverse direction: the reference re-read these exact bytes and agreed on size and SAID.
        assert!(case.reparse.raw_identical, "case {} did not re-serialize", case.name);
        assert_eq!(case.reparse.size, case.raw_byte_size, "case {}", case.name);
        assert_eq!(case.reparse.said, case.said, "case {}", case.name);
    }
    Ok(())
}

/// The pinned unit test's own vectors, and why Rust cannot express their inputs.
#[test]
fn the_upstream_unit_test_vectors_are_pinned_and_their_inputs_refused() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let unit = &fixture.upstream_unit_test;
    assert_eq!(unit.source, "test/app/exchanging.test.ts");
    // The two identifiers that test asserts verbatim.
    assert_eq!(unit.no_embeds.said, "EPWm8LWxxQXmXlB8gbTZKDy7NIwXxpx49N_ZYTa5QkJV");
    assert_eq!(unit.with_embeds.said, "EOK2xNjB5xlSvizCUrkFKbdF4j1nsGpvt6TR1HL0wvaY");
    assert_eq!(
        unit.with_embeds.attachments,
        "-LAZ5AACAA-e-icpAAAPkMTS3LrrhVuQB0k4UndDN0xIfEiKYaN7rTlQ_q9ImnBcugwNO8VWTALXzWoaldJEC1IOpEGkEnjZfxxIleoI"
    );
    assert_eq!(unit.no_embeds.attachments, "");
    assert!(unit.no_embeds.raw.contains(r#""i":"test""#));
    assert_ne!(unit.note, "");
    assert_ne!(unit.rust_decision, "");

    // Each of the three inputs is refused on its own.
    assert!(IdentifierPrefix::from_qb64(&unit.sender).is_err());
    assert!(IdentifierPrefix::from_qb64(&unit.recipient).is_err());
    assert!(Timestamp::parse(&unit.timestamp).is_err());

    // The same message shape, with real identifiers and the reference's own stamp format, is
    // proven byte for byte by the recorded cases; the transposition is identical apart from the
    // embed label.
    let bare = fixture
        .cases
        .iter()
        .find(|case| case.name == "embed_with_bare_signature")
        .ok_or("missing bare-signature case")?;
    assert_eq!(
        bare.attachments,
        format!("-LAZ5AACAA-e-icp{}", fixture.signature),
        "the transposed group differs from the one the unit test asserts",
    );
    Ok(())
}

#[test]
fn the_pathed_counter_bound_matches_the_reference() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let boundary = &fixture.count_boundary;
    let event = SerializedEvent::parse(fixture.embedded_events.vcp.as_bytes())?;
    let embed = ExchangeEmbed::new("icp", &event)?;

    // The widest accepted attachment fills the counter exactly, leaving room for the path.
    assert_eq!(boundary.path_quadlets, 3);
    assert_eq!(boundary.max_accepted.quadlets, 4095);
    assert_eq!(
        boundary.max_accepted.attachment_length,
        (boundary.max_accepted.quadlets - boundary.path_quadlets) * 4
    );
    let widest = embed
        .clone()
        .with_attachment(vec![b'A'; boundary.max_accepted.attachment_length])?;
    let message = ExchangeBuilder::new(
        "/x",
        IdentifierPrefix::from_qb64("EIflL4H4134zYoRM6ls6Q086RLC_BhfNFh5uk-WxvhsL")?,
        IdentifierPrefix::from_qb64("EAKUR-LmLHWMwXTLWQ1QjxHrihBmwwrV2tYaSG7hOrWj")?,
        Timestamp::parse("2023-08-30T17:22:54.183000+00:00")?,
    )
    .embeds(vec![widest])
    .build()?;

    // The fixture elides the 16 KiB body; its prefix, length, and digest are recorded instead, and
    // the body is a single repeated character, so the bytes are pinned without storing them.
    let attachments = core::str::from_utf8(message.attachments())?;
    assert_eq!(attachments.len(), boundary.max_accepted.attachments_length);
    assert!(attachments.starts_with(&boundary.max_accepted.attachments_prefix));
    assert!(
        attachments
            .get(boundary.max_accepted.attachments_prefix.len()..)
            .is_some_and(|tail| tail.bytes().all(|byte| byte == b'A'))
    );
    assert_eq!(boundary.max_accepted.attachments_sha256.len(), 64);

    // One quadlet more and both implementations refuse.
    assert!(boundary.rejected.threw);
    assert!(boundary.rejected.error_message.contains("Invalid count=4096"));
    assert!(matches!(
        embed.with_attachment(vec![b'A'; (boundary.rejected.quadlets - boundary.path_quadlets) * 4]),
        Err(EventError::AttachmentTooLarge { quadlets: 4096, .. })
    ));
    Ok(())
}

#[test]
fn reference_quirks_are_pinned_and_safely_diverged() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let quirks = &fixture.reference_quirks;
    let sender = IdentifierPrefix::from_qb64("EIflL4H4134zYoRM6ls6Q086RLC_BhfNFh5uk-WxvhsL")?;
    let recipient = IdentifierPrefix::from_qb64("EAKUR-LmLHWMwXTLWQ1QjxHrihBmwwrV2tYaSG7hOrWj")?;
    let stamp = Timestamp::parse("2023-08-30T17:22:54.183000+00:00")?;
    let builder = || ExchangeBuilder::new("/x", sender.clone(), recipient.clone(), stamp.clone());

    // 1. The timestamp defaults to the system clock.
    let clock = &quirks.the_timestamp_defaults_to_the_system_clock;
    assert_eq!(clock.length, Timestamp::LENGTH);
    assert_eq!(clock.shape, "9999-99-99T99:99:99.999999+99:99");
    assert_ne!(clock.note, "");
    assert!(clock.rust_decision.contains("required"));

    // 2. Sender and recipient are free text upstream.
    let unvalidated = &quirks.sender_and_recipient_are_unvalidated_text;
    assert!(unvalidated.raw.contains(r#""i":"test""#));
    assert!(unvalidated.raw.contains(r#""rp":"not-a-prefix""#));
    assert_ne!(unvalidated.note, "");
    assert!(
        unvalidated
            .rust_decision
            .as_deref()
            .is_some_and(|decision| decision.contains("IdentifierPrefix"))
    );
    assert!(IdentifierPrefix::from_qb64("not-a-prefix").is_err());

    // 3. A payload field named `i` silently readdresses the attribute block.
    let overrides = &quirks.the_payload_overrides_the_recipient;
    assert!(
        overrides
            .raw
            .contains(r#""rp":"EAKUR-LmLHWMwXTLWQ1QjxHrihBmwwrV2tYaSG7hOrWj""#)
    );
    assert!(
        overrides
            .raw
            .contains(r#""a":{"i":"EOTHERTHANTHERECIPIENT_00000000000000000000","m":"hi"}"#)
    );
    assert_eq!(
        overrides.rust_error_category.as_deref(),
        Some("PayloadOverridesRecipient")
    );
    let mut payload = Sad::new();
    payload.insert("i", SadValue::text("EOTHERTHANTHERECIPIENT_00000000000000000000"))?;
    assert!(matches!(
        builder().payload(payload).build(),
        Err(EventError::PayloadOverridesRecipient { label: "i" })
    ));

    // 11. Neither the payload nor the modifiers have to be maps.
    let loose = &quirks.the_payload_and_modifiers_need_not_be_maps;
    assert!(loose.string_payload.contains(r#""a":{"0":"h","1":"e""#));
    assert!(loose.array_payload.contains(r#""a":{"0":1,"1":2"#));
    assert!(loose.null_modifiers.contains(r#""q":null"#));
    assert!(loose.string_modifiers.contains(r#""q":"mods""#));
    assert_ne!(loose.note, "");
    assert_ne!(loose.rust_decision, "");
    // Rust always writes both as blocks.
    let message = builder().build()?;
    assert!(core::str::from_utf8(message.raw())?.contains(r#""q":{}"#));
    Ok(())
}

/// The embed-label and attachment defects, which are where the reference's transposition can
/// reshape or corrupt the CESR stream a recipient parses.
#[test]
fn reference_embed_quirks_are_pinned_and_safely_diverged() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let quirks = &fixture.reference_quirks;
    let event = SerializedEvent::parse(fixture.embedded_events.vcp.as_bytes())?;

    // 4. An embed labelled `d` is overwritten by the block's own identifier.
    let destroyed = &quirks.an_embed_labelled_d_destroys_itself;
    assert!(destroyed.raw.contains(r#""e":{"d":"E"#));
    assert!(!destroyed.raw.contains(r#""vcp""#));
    assert_eq!(destroyed.rust_error_category.as_deref(), Some("ReservedEmbedLabel"));
    assert!(matches!(
        ExchangeEmbed::new("d", &event),
        Err(EventError::ReservedEmbedLabel { label: "d" })
    ));

    // 5. An embed labelled `v` makes the block look like a versioned message.
    let versioned = &quirks.an_embed_labelled_v_throws;
    assert!(versioned.threw);
    assert!(versioned.error_message.contains("Invalid version string"));
    assert_ne!(versioned.note, "");
    assert_eq!(versioned.rust_error_category, "ReservedEmbedLabel");
    assert!(matches!(
        ExchangeEmbed::new("v", &event),
        Err(EventError::ReservedEmbedLabel { label: "v" })
    ));

    // 6. A label carrying the path separator names a different field once parsed.
    let separator = &quirks.a_separator_in_a_label_changes_the_path;
    assert!(separator.attachments.contains("-e-a-b"));
    assert_ne!(separator.note, "");
    assert_eq!(separator.rust_error_category, "InvalidEmbedLabel");
    assert!(matches!(
        ExchangeEmbed::new("a-b", &event),
        Err(EventError::InvalidEmbedLabel { .. })
    ));

    // 7. An empty label produces an identity path step.
    let empty = &quirks.an_empty_label_is_accepted;
    assert!(empty.attachments.contains("-e-"));
    assert_eq!(empty.rust_error_category, "InvalidEmbedLabel");
    assert!(matches!(
        ExchangeEmbed::new("", &event),
        Err(EventError::InvalidEmbedLabel { .. })
    ));

    // 8. Numeric labels are enumerated first whatever the insertion order.
    let numeric = &quirks.numeric_labels_are_hoisted;
    let embeds_block = numeric.raw.split(r#""e":"#).nth(1).ok_or("no embeds block")?;
    let first = embeds_block.find(r#""1""#).ok_or("no label 1")?;
    let second = embeds_block.find(r#""2""#).ok_or("no label 2")?;
    let third = embeds_block.find(r#""a""#).ok_or("no label a")?;
    assert!(first < second && second < third, "insertion order was 2, 1, a");
    assert_eq!(numeric.rust_error_category.as_deref(), Some("InvalidEmbedLabel"));
    assert!(matches!(
        ExchangeEmbed::new("2", &event),
        Err(EventError::InvalidEmbedLabel { .. })
    ));

    // 9. A misaligned attachment loses its tail from the count.
    let misaligned = &quirks.a_misaligned_attachment_truncates_its_count;
    assert!(misaligned.attachments.ends_with("ABC"));
    // The recorded count covers three quadlets, twelve characters, while the group is fifteen.
    assert!(misaligned.attachments.starts_with("-LAD"));
    assert_eq!(misaligned.attachments.len(), 19);
    assert_eq!(misaligned.rust_error_category, "NonIntegralAttachment");
    assert!(matches!(
        ExchangeEmbed::new("icp", &event)?.with_attachment(b"ABC".to_vec()),
        Err(EventError::NonIntegralAttachment { length: 3, .. })
    ));

    // 10. Arbitrary bytes are injected into the CESR stream verbatim.
    let injected = &quirks.a_non_cesr_attachment_is_embedded_verbatim;
    assert!(injected.attachments.ends_with(r#"{"a""#));
    assert_eq!(injected.rust_error_category, "InvalidAttachmentText");
    assert!(matches!(
        ExchangeEmbed::new("icp", &event)?.with_attachment(br#"{"a""#.to_vec()),
        Err(EventError::InvalidAttachmentText { offset: 0, .. })
    ));
    Ok(())
}
